using System.Text;

namespace TrivexTechPrintAgent.Services;

/// <summary>
/// Pre-rendered 192x192 1-bit logo as a ready-to-send ESC/POS raster command (GS v 0).
/// To change the logo, regenerate this Base64 string from your own image.
/// </summary>
public static class LogoData
{
    private const string Base64 =
        "";

    public static string GetEscPosString()
        => Encoding.Latin1.GetString(Convert.FromBase64String(Base64));
}
